    @Mock
    private XmlReadContext parentContext;

    // Constants to match internal XMLTokenStream logic if applicable, 
    // otherwise we mock the behavior via xmlReader/xmlTokens
    private static final int XML_START_ELEMENT = 1;
    private static final int XML_END_ELEMENT = 2;
    private static final int XML_ATTRIBUTE_NAME = 3;
    private static final int XML_ATTRIBUTE_VALUE = 4;
    private static final int XML_TEXT = 5;
    private static final int XML_END = 6;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // Since FromXmlParser is complex, we use a mock-heavy approach to simulate the internal state
        // via reflection where necessary, or rely on the constructor.
        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Injecting mocks into private fields using reflection to control state
        setField(parser, "_parsingContext", parsingContext);
        when(parsingContext.getParent()).thenReturn(parentContext);
        when(parentContext.getNamesToWrap()).thenReturn(null);

        // Mocking the internal _xmlTokens which is usually initialized from the reader
        // In a real scenario, we'd mock the XmlTokenStream object.
        // For this test, we assume the parser uses the xmlReader to drive the token stream.
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testNextTextValue_WhenNextTokenAlreadySetAsString() throws Exception {
        // Arrange: _nextToken is already set to VALUE_STRING
        setField(parser, "_nextToken", JsonToken.VALUE_STRING);
        setField(parser, "_currText", "hello");

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertEquals("hello", result);
        assertNull(getPrivateField(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_WhenNextTokenIsOtherAndCallsUpdateState() throws Exception {
        // Arrange
        setField(parser, "_nextToken", JsonToken.START_OBJECT);

        // Act
        String result = parser.nextTextValue();

        // Assert
        assertNull(result);
        assertEquals(JsonToken.START_OBJECT, getPrivateField(parser, "_currToken"));
    }

